insert into opportunities (id, title, url, raw_text, lang, content_hash, status, captured_at) values ('63a13cfa-7061-4822-b80a-62d7bef8ec30', 'Lead Data Analyst, Growth — Copperleaf Health', 'https://jobs.example.com/copperleaf-health/61882', 'Lead Data Analyst, Growth at Copperleaf Health. Location: Remote - Worldwide. Join the growth team at a fast-growing saas company. You will own acquisition and retention analytics end to end: funnel analysis, cohort retention, pricing tests and lifecycle campaigns. Daily work is SQL and Python; you will run A/B tests with the product team and present results to leadership. Experience with Tableau or Looker is a plus. Fully remote, async-friendly culture. Salary: $130,000 - $160,000 per year.', 'en', 'b10decdb33a0410b0bc4e07e27efde44a7ebd16593c636cd11a3cb853927dc88', 'applied', now() - interval '4158000 seconds');
insert into opportunities (id, title, url, raw_text, lang, content_hash, status, captured_at) values ('68f35628-9bc6-40ed-9b30-ab60aaaf6e90', 'Senior Product Analyst — Juniper Mobility', 'https://jobs.example.com/juniper-mobility/72981', 'Senior Product Analyst at Juniper Mobility. Location: Remote (LATAM). We are looking for a senior analyst to own our experimentation program. You will design and analyze A/B tests, size opportunities with SQL and Python, and partner with product managers on the roadmap of our marketplace platform. You will build the statistics behind our test readouts and coach teams on experiment design. Our stack: BigQuery, Looker and Python notebooks. We are a remote-first team across the Americas and Europe. Salary: $135,000 - $155,000 per year.', 'en', '86d8cdbe39932b308f3bdc4dff35a5ffcd0773f0adafb0d978899f9c02eca94e', 'applied', now() - interval '3812400 seconds');
