insert into opportunities (id, title, url, raw_text, lang, content_hash, status, captured_at) values ('4e925675-bf56-48da-9ed2-09e3207a9eda', 'Data Analyst — Talentbridge Staffing', 'https://jobs.example.com/talentbridge-staffing/191448', 'Data Analyst at Talentbridge Staffing. Location: Remote - Worldwide. We need a mid data analyst to build the reporting layer for our client business. You will model data in SQL, build dashboards in Tableau, define KPIs with finance and operations, and automate recurring analyses in Python. You will work with a small data team and have real ownership of the metrics the company runs on. Remote within our hiring regions.', 'en', '0c5d555405193154cda28bb514d553ca95a655987cba44b14c7d70df20350055', 'rejected_by_rules', now() - interval '183600 seconds');
