insert into opportunities (id, title, url, raw_text, lang, content_hash, status, captured_at) values ('54ea3615-3238-4168-b622-c8b7d1c53dd7', 'Senior Product Analyst, Experimentation — Kestrel Markets', 'https://jobs.example.com/kestrel-markets/365734', 'Senior Product Analyst, Experimentation at Kestrel Markets. Location: Remote - Worldwide. We are looking for a senior analyst to own our experimentation program. You will design and analyze A/B tests, size opportunities with SQL and Python, and partner with product managers on the roadmap of our two-sided marketplace platform. You will build the statistics behind our test readouts and coach teams on experiment design. Our stack: BigQuery, Looker and Python notebooks. We are a remote-first team across the Americas and Europe. Salary: $140,000 - $170,000 per year.', 'en', '85b88232a43ae655ec8974d02913a8fef4905ec0a344f05469c76daf35a2bb72', 'scored', now() - interval '97200 seconds');
insert into opportunities (id, title, url, raw_text, lang, content_hash, status, captured_at) values ('f8a4ac9e-9aac-4956-b533-9872afda9e1c', 'Senior Data Analyst — Saltmarsh Logistics', 'https://jobs.example.com/saltmarsh-logistics/537072', 'Senior Data Analyst at Saltmarsh Logistics. Location: Remote - Worldwide. Senior Data Analyst at Saltmarsh Logistics. Remote. SQL, Python. Salary: $100,000 - $130,000 per year.', 'en', '2b487b4c715a583ff7c9bbae2ee8bb4f6ba17d73a04fef67da488901d6245aa9', 'scored', now() - interval '97200 seconds');
